// Where an index is in its life. `creating`: not usable yet. `ready`: the only state that answers
// searches. `recreate_required`: answers nothing until it is deleted, created again and its documents
// written again. `deleting`: deletion is in progress. `delete_failed`: deletion did not finish and is
// retried.
// Ref: #/components/schemas/IndexState
type IndexState string

const (
	IndexStateCreating         IndexState = "creating"
	IndexStateReady            IndexState = "ready"
	IndexStateRecreateRequired IndexState = "recreate_required"
	IndexStateDeleting         IndexState = "deleting"
	IndexStateDeleteFailed     IndexState = "delete_failed"
)

// AllValues returns all IndexState values.
func (IndexState) AllValues() []IndexState {
	return []IndexState{
		IndexStateCreating,
		IndexStateReady,
		IndexStateRecreateRequired,
		IndexStateDeleting,
		IndexStateDeleteFailed,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s IndexState) MarshalText() ([]byte, error) {
	switch s {
	case IndexStateCreating:
		return []byte(s), nil
	case IndexStateReady:
		return []byte(s), nil
	case IndexStateRecreateRequired:
		return []byte(s), nil
	case IndexStateDeleting:
		return []byte(s), nil
	case IndexStateDeleteFailed:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *IndexState) UnmarshalText(data []byte) error {
	switch IndexState(data) {
	case IndexStateCreating:
		*s = IndexStateCreating
		return nil
	case IndexStateReady:
		*s = IndexStateReady
		return nil
	case IndexStateRecreateRequired:
		*s = IndexStateRecreateRequired
		return nil
	case IndexStateDeleting:
		*s = IndexStateDeleting
		return nil
	case IndexStateDeleteFailed:
		*s = IndexStateDeleteFailed
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

