// One match, or several matches that share lines, together with the lines it covers. A result covers
// one line unless the query set multiline and a match spans lines.
// Ref: #/components/schemas/QueryResult
type QueryResult struct {
	// The key of the document that matched.
	Key string `json:"key"`
	// The revision of the document that matched.
	Revision string `json:"revision"`
	// One-based number of the first line the result covers.
	LineNumber int `json:"line_number"`
	// One-based number of the last line the result covers. Equal to line_number unless a match spans
	// lines.
	LastLineNumber int `json:"last_line_number"`
	// Byte offset of the first covered line's start within the document.
	LineStartOffset int `json:"line_start_offset"`
	// Byte offset just past the last covered line, excluding its line break.
	LineEndOffset int `json:"line_end_offset"`
	// Byte offset of the first byte of text within the document.
	TextStartOffset int `json:"text_start_offset"`
	// One-based number of the line text begins on. Equal to line_number unless text was cut at its start.
	TextLineNumber int `json:"text_line_number"`
	// The covered lines, up to 64 KiB, centered on the first match when they are longer. Line breaks
	// between covered lines are kept; the last line's break is not.
	Text string `json:"text"`
	// Every match on the covered lines that lies at least partly within text, with byte offsets and
	// lengths relative to the document. A match that consumed the last line's break extends one byte past
	// text.
	Matches []Match `json:"matches"`
	// Whether text was cut at either end.
	TextTruncated bool `json:"text_truncated"`
	// Whether matches were left out, because there were more than 4096 or because they lie outside text.
	MatchesTruncated bool `json:"matches_truncated"`
	// The requested lines before the result, in document order, ending at the line just above its first
	// line. Fewer are returned at the start of the document, and the field is omitted when there are none.
	LinesBefore []ContextLine `json:"lines_before"`
	// The requested lines after the result, in document order, starting at the line just below its last
	// line. Fewer are returned at the end of the document, and the field is omitted when there are none.
	LinesAfter []ContextLine `json:"lines_after"`
}

